import{z as l,x as s,o as e,c as m,q as A,j as B,D as E,d as t,s as n,S as o,b as i}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"优化器的数值稳定性","description":"","frontmatter":{"title":"优化器的数值稳定性","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pf-optimizer-numerics.md","filePath":"quant/pf-optimizer-numerics.md","lastUpdated":1791413859000}'),d={name:"quant/pf-optimizer-numerics.md"};function p(u,a,h,c,f,D){const r=s("Mermaid");return e(),m("div",null,[a[2]||(a[2]=A('<h1 id="优化器的数值稳定性" tabindex="-1">优化器的数值稳定性 <a class="header-anchor" href="#优化器的数值稳定性" aria-label="Permalink to &quot;优化器的数值稳定性&quot;">​</a></h1><div class="epigraph"><p>优化器从不同情输入：它把病态的协方差矩阵变成一个自信满满的角点解；权重的大幅跳动常常不是观点变了，是条件数变了。</p><footer>—— 据 Michaud, The Markowitz Optimization Enigma, Financial Analysts Journal, 1989；Markowitz, Journal of Finance, 1952 整理</footer></div><p><a href="/quant/fz-map">上一课</a>把因子研究深化收束：从构造、正交化、拥挤、生命周期到报告与复现的十环流水线，每一环的结论都声明「相对什么成立」，并留下接口——因子确定之后的权重与优化，交给组合构建的课程。本课就是那门课的第一课。在讨论任何聪明的目标函数之前，先把最底下一层钉住：同一个二次规划，换一台机器、多一天数据，权重为什么面目全非。后课的正则化、黑盒与再平衡，都默认你已能把组合问题写成数值上站得住的形式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/quant/markowitz">Markowitz</a> 的选择问题写下来只有一行：给定 \\(\\mu\\) 与 \\(\\Sigma\\)，在预算与收益约束下最小化 \\(w^\\top\\Sigma w\\)。数学上良定，数值上未必。输入的每一项都带误差：\\(N\\) 只资产只有 \\(T\\) 个观测，样本协方差的秩至多 \\(T-1\\)，\\(N \\gt T\\) 时直接奇异；即便满秩，特征值谱也能横跨多个数量级。优化器拿到条件数 \\(10^8\\) 量级的 \\(\\Sigma\\)，算出的权重就带着假精度：沿小特征值方向移动权重，目标值几乎不变，解的唯一性丢失，求解器停在哪一点由舍入误差与初值决定。<span class="marginnote">条件数就是矩阵「最大特征值除以最小特征值」的倍数，衡量输入误差被放大的程度。数字实例：条件数 1000 时，输入里 0.1% 的误差就可能在解里放大成 100% 量级的权重移动；条件数 \\(10^8\\) 时，小数点后任何一位的权重都只是舍入误差的化妆。</span>不这么做的错法很具体：把权重跳变解读为信号变化照单执行；把求解器报错当成「无解」；两台机器跑出两份仓位，对不上账。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把数值稳定性当成求解前的一道固定工序：数据进来先过尺度与谱的体检，体检通过才许进求解器；解出来再过 KKT 残差与扰动两道验收，任何一道不过就退回上游修输入，而不是解读权重。四步各有可判定的判据，全部可脚本化——同一份数据在任何一台机器上都该给出同一组权重。</p><h3 id="从输入到验收" tabindex="-1">从输入到验收 <a class="header-anchor" href="#从输入到验收" aria-label="Permalink to &quot;从输入到验收&quot;">​</a></h3><p>做法分四步。其一，尺度统一：收益与协方差用同一频率、同一年化口径，\\(\\mu\\) 与 \\(\\Sigma\\) 的时间尺度错配是无声的放大器；再对 \\(\\Sigma\\) 做对角预条件 \\(D^{-1/2}\\Sigma D^{-1/2}\\)，解出 \\(v\\) 后回乘 \\(w=D^{-1/2}v\\)，数值行为立改，解不变。<span class="marginnote">预条件就是「先给问题换一套单位再求解」：把每只资产按自身波动缩放，让矩阵各方向量级接近。直觉类比：用同一台毫克精度的秤去称大象和蚂蚁，读数都会疯；先换成各自合适的量纲，读数立刻稳定——最优解没变，变的只是数值行为。</span>其二，秩与谱检查：数一数 \\(N\\) 与 \\(T\\)，看特征值谱的尾部；接近奇异就先收缩或降维——<a href="/quant/cov-shrinkage">估计误差与收缩</a>、<a href="/quant/ledoit-wolf">Ledoit-Wolf 收缩</a>与<a href="/quant/factor-vs-sample-cov">因子协方差 vs 样本</a>已写满工具箱，这里要把它们当数值前置步骤执行，而不是统计学装饰。其三，求解器与容差：有效集法与内点法在退化方向上可以给出不同解，容差应与输入的不确定度相称——报出小数点后十二位的权重是自我欺骗。其四，验收用 KKT 加扰动：对偶可行性残差要过线；再对数据扰动——重抽日期、增删一天、把 \\(\\mu\\) 推动一个标准误——量一量权重跳多少。</p>',9)),(e(),B(o,null,{default:E(()=>[n(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E8%BE%93%E5%85%A5%20mu%20%E4%B8%8E%20Sigma%22%5D%20--%3E%20SCALE%5B%22%E5%B0%BA%E5%BA%A6%E7%BB%9F%E4%B8%80%E4%B8%8E%E5%AF%B9%E8%A7%92%E9%A2%84%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20SCALE%20--%3E%20RANK%5B%22%E7%A7%A9%E4%B8%8E%E6%9D%A1%E4%BB%B6%E6%95%B0%E6%A3%80%E6%9F%A5%22%5D%0A%20%20RANK%20--%3E%20SOLVE%5B%22QP%20%E6%B1%82%E8%A7%A3%EF%BC%9A%E6%9C%89%E6%95%88%E9%9B%86%E6%88%96%E5%86%85%E7%82%B9%22%5D%0A%20%20SOLVE%20--%3E%20KKT%5B%22KKT%20%E6%AE%8B%E5%B7%AE%E9%AA%8C%E6%94%B6%22%5D%0A%20%20KKT%20--%3E%20PERT%5B%22%E6%89%B0%E5%8A%A8%E6%B5%8B%E8%AF%95%EF%BC%9A%E6%9D%83%E9%87%8D%E7%9A%84%E7%A8%B3%E5%AE%9A%E5%B8%A6%22%5D%0A%20%20PERT%20--%3E%7C%E4%B8%8D%E9%80%9A%E8%BF%87%7C%20RANK%0A%20%20PERT%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20OUT%5B%22%E5%8F%AF%E5%A4%8D%E7%8E%B0%E7%9A%84%E6%9D%83%E9%87%8D%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[t("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"条件数为什么能杀死 Markowitz：有效前沿沿小特征值方向几乎平坦，目标函数分辨不出这条方向上的权重差别，「最优解」成了一片平坦谷底上的集合。约束再把它推向顶点：非负与暴露上限让活跃集变化成为离散事件，数据的微小扰动可以翻转哪些名字被顶在边界上——权重从 \\(3\\%\\) 跳到 \\(0\\)，与从 \\(3\\%\\) 跳到 \\(2.9\\%\\)，是两种完全不同的运营事件。Michaud 在 1989 年把这层病说得最狠：无约束的优化器把估计误差当信息放大，样本内「最优」恰是样本外最脆的。数值不稳定是这句话的表层症状：连同一份数据都给不出同一组权重的东西，谈不上统计稳健；而两份稳定但不同的解，往往提示该把活跃集与退化方向写进报告。",-1)),(e(),B(o,null,{default:E(()=>[n(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20E1%5B%22%E8%BE%93%E5%85%A5%E5%B8%A6%E4%BC%B0%E8%AE%A1%E8%AF%AF%E5%B7%AE%EF%BC%9AN%20%E5%A4%A7%20T%20%E5%B0%8F%22%5D%20--%3E%20E2%5B%22%E7%89%B9%E5%BE%81%E5%80%BC%E8%B0%B1%E6%A8%AA%E8%B7%A8%E5%A4%9A%E4%B8%AA%E6%95%B0%E9%87%8F%E7%BA%A7%22%5D%0A%20%20E2%20--%3E%20E3%5B%22%E5%B0%8F%E7%89%B9%E5%BE%81%E5%80%BC%E6%96%B9%E5%90%91%E4%B8%8A%E7%9B%AE%E6%A0%87%E5%80%BC%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8F%98%22%5D%0A%20%20E3%20--%3E%20E4%5B%22%E6%9C%89%E6%95%88%E5%89%8D%E6%B2%BF%E5%9C%A8%E8%BF%99%E4%BA%9B%E6%96%B9%E5%90%91%E4%B8%8A%E5%B9%B3%E5%9D%A6%22%5D%0A%20%20E4%20--%3E%20E5%5B%22%E3%80%8C%E6%9C%80%E4%BC%98%E8%A7%A3%E3%80%8D%E5%8F%98%E6%88%90%E4%B8%80%E6%95%B4%E7%89%87%E9%9B%86%E5%90%88%22%5D%0A%20%20E5%20--%3E%20E6%5B%22%E7%BA%A6%E6%9D%9F%E6%8A%8A%E8%A7%A3%E6%8E%A8%E5%88%B0%E5%8F%AF%E8%A1%8C%E9%9B%86%E9%A1%B6%E7%82%B9%22%5D%0A%20%20E6%20--%3E%20E7%5B%22%E6%95%B0%E6%8D%AE%E5%BE%AE%E6%89%B0%E4%BD%BF%E6%9D%83%E9%87%8D%E7%A6%BB%E6%95%A3%E8%B7%B3%E5%8F%98%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">常见误区：看到权重从 3% 跳到 0 就以为观点变了。先查三件事再下结论：数据是不是多了一天、协方差的条件数有没有变化、求解器版本与容差是否一致——数值性跳变该修输入，信号性跳变才该调仓，两者的运营动作完全不同。</span></p><p><span class="marginnote">\\(N\\) 只资产、\\(T\\) 个观测，样本协方差的秩至多 \\(T-1\\)：500 只股票配一年日频（\\(T=250\\)），\\(w^\\top\\Sigma w\\) 沿一半以上的方向没有任何数据证据——优化器在那里自由发挥。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重推收缩公式，不进入约束的语义学：多空、净毛暴露与章程如何改写可行集，见<a href="/quant/long-short-constraints">多空与多头约束</a>与<a href="/quant/portfolio-constraints">组合约束</a>。数值稳定不等于统计稳健——解可以稳定地错，扰动验收只证明「对输入敏感度低」，不证明输入正确。整数约束、基数限制与凸不起来的目标，凸求解器无能为力，是下一课黑盒优化器的对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>组合优化先过数值关：尺度统一、预条件、秩与条件数检查是求解的前置步骤，不是可选卫生。</li><li>\\(N \\gt T\\) 或病态谱让解不唯一；顶点解对数据扰动离散跳变，权重跳变要先查数值再解读信号。</li><li>验收标准是 KKT 残差加扰动测试：报告权重的同时报告它的稳定带。</li><li>数值稳定与统计稳健是两件事：收缩与降维解决后者，求解器容差只解决前者。</li><li>出处：据 Markowitz, <em>Journal of Finance</em>, 1952；Michaud, <em>Financial Analysts Journal</em>, 1989 的口径整理。</li></ul>',6))])}const C=l(d,[["render",p]]);export{F as __pageData,C as default};
